1	package app
2	
3	import (
4		"strings"
5		"testing"
6	
7		"github.com/charmbracelet/lipgloss"
8	
9		"github.com/anthnel/devdesk/internal/ui/shortcut"
10		"github.com/anthnel/devdesk/internal/ui/testutil"
11	)
12	
13	func manyShortcuts(n int) shortcut.Shortcuts {
14		out := make(shortcut.Shortcuts, 0, n)
15		for i := range n {
16			out = append(out, shortcut.Shortcut{Key: string(rune('a' + i%26)), Description: "Do the thing"})
17		}
18		return out
19	}
20	
21	// ── Fixed height ─────────────────────────────────────────────────────────────
22	
23	// The header is a fixed seven rows. resize() budgets the viewport against it,
24	// so a header that grew with the shortcut count would push the last table row
25	// off the bottom of the window.
26	func TestTheHeaderIsAlwaysSevenRows(t *testing.T) {
27		for _, n := range []int{0, 1, 7, 8, 20, 40} {
28			got := lipgloss.Height(renderHeaderContent(
29				[]shortcut.HeaderInfo{{Key: "Context", Value: "default"}},
30				manyShortcuts(n),
31				180,
32			))
33			if got != headerMinHeight {
34				t.Errorf("with %d shortcuts the header is %d rows, want %d", n, got, headerMinHeight)
35			}
36		}
37	}
38	
39	func TestBuildShortcutLinesAlwaysFillsTheColumn(t *testing.T) {
40		for _, n := range []int{0, 3, 11, 30} {
41			if got := len(buildShortcutLines(manyShortcuts(n), 60)); got != headerMinHeight {
42				t.Errorf("with %d shortcuts buildShortcutLines returned %d lines, want %d", n, got, headerMinHeight)
43			}
44		}
45	}
46	
47	// Shortcuts overflow into a second column rather than being dropped: the header
48	// height is fixed, so the only alternative to wrapping is losing them.
49	func TestShortcutsOverflowIntoASecondColumn(t *testing.T) {
50		oneColumn := buildShortcutLines(manyShortcuts(headerMinHeight), 200)
51		twoColumns := buildShortcutLines(manyShortcuts(headerMinHeight+1), 200)
52	
53		if lipgloss.Width(twoColumns[0]) <= lipgloss.Width(oneColumn[0]) {
54			t.Errorf("an eighth shortcut did not widen the block: %d then %d",
55				lipgloss.Width(oneColumn[0]), lipgloss.Width(twoColumns[0]))
56		}
57	}
58	
59	// ── Width ────────────────────────────────────────────────────────────────────
60	
61	// Every row is exactly the window width — no shorter, which would show the
62	// terminal's own background through the header (Rule 115), and no longer, which
63	// would wrap and cost the viewport a row. 80 is the case that used to overflow:
64	// the shortcut block is clipped to its column, not merely padded (D18).
65	func TestEveryHeaderRowFillsTheWidth(t *testing.T) {
66		for _, width := range []int{80, 120, 180, 240} {
67			rendered := renderHeaderContent(
68				[]shortcut.HeaderInfo{{Key: "Context", Value: "default"}},
69				manyShortcuts(12),
70				width,
71			)
72			for i, line := range strings.Split(rendered, "\n") {
73				if got := lipgloss.Width(line); got != width {
74					t.Errorf("at width %d, row %d is %d wide", width, i, got)
75				}
76			}
77		}
78	}
79	
80	// Clipping must not cut an escape sequence in half: the truncated row would
81	// leak its colour onto everything rendered after it, which is the corruption
82	// Rule 122 is about.
83	func TestClippingTheShortcutBlockLeavesTheStylingIntact(t *testing.T) {
84		testutil.TrueColor(t)
85	
86		rendered := renderHeaderContent(
87			[]shortcut.HeaderInfo{{Key: "Context", Value: "default"}},
88			manyShortcuts(12),
89			80,
90		)
91	
92		for i, line := range strings.Split(rendered, "\n") {
93			if truncated(line) {
94				t.Errorf("row %d ends inside an escape sequence: %q", i, line)
95			}
96		}
97	}
98	
99	// truncated reports whether the line holds an escape sequence that was never
100	// terminated — the shape a naive slice leaves behind.
101	func truncated(line string) bool {
102		for _, after := range strings.Split(line, "\x1b[")[1:] {
103			end := strings.IndexByte(after, 'm')
104			if end < 0 || strings.Contains(after[:end], "\x1b") {
105				return true
106			}
107		}
108		return false
109	}
110	
111	// A window too narrow for the logo alone must not produce a negative column
112	// width — lipgloss would panic on the repeat.
113	func TestTheHeaderSurvivesAWindowNarrowerThanTheLogo(t *testing.T) {
114		rendered := renderHeaderContent(
115			[]shortcut.HeaderInfo{{Key: "Context", Value: "default"}},
116			manyShortcuts(4),
117			30,
118		)
119	
120		if lipgloss.Height(rendered) != headerMinHeight {
121			t.Errorf("the header is %d rows at width 30, want %d", lipgloss.Height(rendered), headerMinHeight)
122		}
123	}
124	
125	// ── Content ──────────────────────────────────────────────────────────────────
126	
127	// Values align on the longest key, which is what makes the info block readable
128	// as a column rather than a ragged list.
129	func TestInfoValuesAlignOnTheLongestKey(t *testing.T) {
130		lines := buildInfoLines([]shortcut.HeaderInfo{
131			{Key: "URL", Value: "gitlab.com"},
132			{Key: "Context", Value: "default"},
133		}, 40)
134	
135		first := strings.Index(lines[0], "gitlab.com")
136		second := strings.Index(lines[1], "default")
137		if first != second {
138			t.Errorf("values start at columns %d and %d; they should align", first, second)
139		}
140	}
141	
142	func TestInfoLinesPadOutToTheHeaderHeight(t *testing.T) {
143		lines := buildInfoLines([]shortcut.HeaderInfo{{Key: "Context", Value: "default"}}, 40)
144	
145		if len(lines) != headerMinHeight {
146			t.Fatalf("buildInfoLines returned %d lines, want %d", len(lines), headerMinHeight)
147		}
148		for i := 1; i < len(lines); i++ {
149			if lines[i] != "" {
150				t.Errorf("line %d is %q, want it empty", i, lines[i])
151			}
